WatchFace({
  initView() {
    // the picked variant survives a restart (when the watch offers storage)
    let variantIdx = 0
    try { if (typeof hmFS !== 'undefined') variantIdx = Number(hmFS.SysProGetInt('dialcraft_variant')) || 0 } catch (e) {}

    // layers with a code handle: W.<handle> is the widget, F.<handle> the picture list of a variants layer
    const W = {}
    const F = {}
    // Background (FILL_RECT)
    ui.createWidget(ui.widget.FILL_RECT, {
      x: px(0),
      y: px(0),
      w: px(390),
      h: px(450),
      color: 0x000000,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Scene (IMG)
    const variants_0 = [A('scene_day.png'), A('scene_golden.png'), A('scene_sunset.png'), A('scene_dusk.png'), A('scene_night.png'), A('scene_dawn.png')]
    const variant_0 = ui.createWidget(ui.widget.IMG, {
      x: px(0),
      y: px(0),
      src: variants_0[variantIdx % variants_0.length],
      show_level: ui.show_level.ONLY_NORMAL
    })
    W.scene = variant_0
    F.scene = variants_0

    // Minute (IMG_TIME)
    ui.createWidget(ui.widget.IMG_TIME, {
      minute_startX: px(206),
      minute_startY: px(46),
      minute_zero: 1,
      minute_space: px(0),
      minute_align: ui.align.LEFT,
      minute_array: img_Minute_34j3,
      minute_follow: 0,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Hour (IMG_TIME)
    ui.createWidget(ui.widget.IMG_TIME, {
      hour_startX: px(56),
      hour_startY: px(46),
      hour_zero: 1,
      hour_space: px(0),
      hour_align: ui.align.LEFT,
      hour_array: img_Hour_31eo,
      hour_follow: 0,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Weekday (IMG_WEEK)
    ui.createWidget(ui.widget.IMG_WEEK, {
      x: px(105),
      y: px(153),
      week_en: img_Weekday_p73i,
      week_sc: img_Weekday_p73i,
      week_tc: img_Weekday_p73i,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Day (IMG_DATE)
    ui.createWidget(ui.widget.IMG_DATE, {
      day_startX: px(159),
      day_startY: px(153),
      day_zero: 0,
      day_space: px(-14),
      day_align: ui.align.LEFT,
      day_follow: 0,
      day_en_array: img_Day_t6o7,
      day_sc_array: img_Day_t6o7,
      day_tc_array: img_Day_t6o7,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Battery (TEXT_IMG)
    ui.createWidget(ui.widget.TEXT_IMG, {
      x: px(208),
      y: px(153),
      type: ui.data_type.BATTERY,
      font_array: img_Battery_p1js,
      h_space: px(-13),
      align_h: ui.align.LEFT,
      unit_en: A('percent.png'),
      unit_sc: A('percent.png'),
      unit_tc: A('percent.png'),
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Steps (TEXT_IMG)
    ui.createWidget(ui.widget.TEXT_IMG, {
      x: px(115),
      y: px(397),
      w: px(150),
      type: ui.data_type.STEP,
      font_array: img_Steps_91uz,
      h_space: px(-21),
      align_h: ui.align.CENTER_H,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Hour Aod (IMG_TIME)
    ui.createWidget(ui.widget.IMG_TIME, {
      minute_startX: px(129),
      minute_startY: px(96),
      minute_zero: 1,
      minute_space: px(0),
      minute_align: ui.align.LEFT,
      minute_array: img_Hour_Aod_s5y0,
      minute_follow: 0,
      show_level: ui.show_level.ONLY_AOD,
    })

    // Minute Aod (IMG_TIME)
    ui.createWidget(ui.widget.IMG_TIME, {
      hour_startX: px(125),
      hour_startY: px(236),
      hour_zero: 1,
      hour_space: px(0),
      hour_align: ui.align.LEFT,
      hour_array: img_Minute_Aod_53km,
      hour_follow: 0,
      show_level: ui.show_level.ONLY_AOD,
    })

    // Colon (IMG)
    ui.createWidget(ui.widget.IMG, {
      x: px(180),
      y: px(46),
      src: A('glass/colon.png'),
      show_level: ui.show_level.ONLY_NORMAL
    })

    // Drops on glass (IMG)
    const variants_1 = [A('drops_day.png'), A('drops_golden.png'), A('drops_sunset.png'), A('drops_dusk.png'), A('drops_night.png'), A('drops_dawn.png')]
    const variant_1 = ui.createWidget(ui.widget.IMG, {
      x: px(0),
      y: px(0),
      src: variants_1[variantIdx % variants_1.length],
      show_level: ui.show_level.ONLY_NORMAL
    })
    W.drops = variant_1
    F.drops = variants_1

    // Rain outside (IMG_ANIM)
    ui.createWidget(ui.widget.IMG_ANIM, {
      x: px(0),
      y: px(0),
      anim_path: 'images/anim',
      anim_prefix: 'rain',
      anim_ext: 'png',
      anim_fps: 12,
      anim_size: 6,
      repeat_count: 0,
      step: 1,
      anim_status: ui.anim_status.START,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Running drops 1 (IMG_ANIM)
    ui.createWidget(ui.widget.IMG_ANIM, {
      x: px(0),
      y: px(20),
      anim_path: 'images/anim',
      anim_prefix: 'run0',
      anim_ext: 'png',
      anim_fps: 6,
      anim_size: 16,
      repeat_count: 0,
      step: 1,
      anim_status: ui.anim_status.START,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Running drops 2 (IMG_ANIM)
    ui.createWidget(ui.widget.IMG_ANIM, {
      x: px(130),
      y: px(20),
      anim_path: 'images/anim',
      anim_prefix: 'run1',
      anim_ext: 'png',
      anim_fps: 6,
      anim_size: 16,
      repeat_count: 0,
      step: 1,
      anim_status: ui.anim_status.START,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Running drops 3 (IMG_ANIM)
    ui.createWidget(ui.widget.IMG_ANIM, {
      x: px(260),
      y: px(20),
      anim_path: 'images/anim',
      anim_prefix: 'run2',
      anim_ext: 'png',
      anim_fps: 6,
      anim_size: 16,
      repeat_count: 0,
      step: 1,
      anim_status: ui.anim_status.START,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // a Tap zone set to "Cycle variants" calls this
    const cycleVariants = () => {
      variantIdx = (variantIdx + 1) % Math.max(variants_0.length, variants_1.length)
      try { if (typeof hmFS !== 'undefined') hmFS.SysProSetInt('dialcraft_variant', variantIdx) } catch (e) {}
      variant_0.setProperty(ui.prop.SRC, variants_0[variantIdx % variants_0.length])
      variant_1.setProperty(ui.prop.SRC, variants_1[variantIdx % variants_1.length])
    }

    // ---- user code (project.userCode) ----
    // px() only takes a literal number (the build replaces it, there is no px at run time); pxv() scales a computed one
    const pxv = (n) => Math.round(n * px(1000) / 1000)
    {
      const NP = 6, PREV = 2, MS = 5000
      const FROM = [[330,1],[480,2],[990,3],[1110,4],[1185,5],[1290,0]]
      let id = null, cur = -1, clock = null
      try { clock = new DCTime() } catch (e) {}
      const minutes = () => {
        try { if (clock) { const h = clock.getHours(), m = clock.getMinutes(); if (typeof h === 'number' && typeof m === 'number') return h * 60 + m } } catch (e) {}
        try { const d = new Date(); return d.getHours() * 60 + d.getMinutes() } catch (e) {}
        return 600
      }
      const phase = (m) => { let p = 0; for (const f of FROM) if (m >= f[0]) p = f[1]; return p }
      const tick = () => {
        const p = phase(minutes())
        if (p === cur) return
        cur = p
        const i = (p - PREV + NP) % NP
        W.scene.setProperty(ui.prop.MORE, { x: pxv(0), y: pxv(0), src: F.scene[i] })
        W.drops.setProperty(ui.prop.MORE, { x: pxv(0), y: pxv(0), src: F.drops[i] })
      }
      const safe = () => { try { tick() } catch (e) {} }
      const stop = () => { if (id === null) return; try { clearInterval(id) } catch (e) {} id = null }
      const start = () => { if (id !== null) return; try { id = setInterval(safe, MS) } catch (e) {} }
      ui.createWidget(ui.widget.WIDGET_DELEGATE, { resume_call: () => { cur = -1; safe(); start() }, pause_call: stop })
      safe()
      start()
    }
  },

  build() {
    this.initView()
  },
})
